SELECT 
FROM task
WHERE user_id = #{userId}
  AND is_deleted = 0
  AND DATE(planned_start_time) = #{date}
ORDER BY planned_start_time ASC

SELECT 
FROM task
WHERE user_id = #{userId}
  AND is_deleted = 0

    AND task_type = #{taskType}


    AND task_status = #{taskStatus}

ORDER BY planned_start_time ASC
